@Service // singleton by default
public class OrderService {
    private final OrderRepository orderRepository;
    private final EmailService emailService;

    public OrderService(OrderRepository repo, EmailService email) {
        this.orderRepository = repo;
        this.emailService = email;
    }

    public Order placeOrder(Long userId, List<OrderItem> items) {
        var order = new Order(userId, items, LocalDateTime.now());
        orderRepository.save(order);
        emailService.sendConfirmation(order);
        return order; // no instance state - stateless operation
    }
}

@Repository // also singleton by default
public class OrderRepository {
    private final JdbcTemplate jdbcTemplate; // shared, thread-safe

    public OrderRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }
}

@Component
@Scope("prototype")
public class OrderProcessor {
    private Order currentOrder; // stateful - holds specific order data
    private ProcessingStatus status;

    public void process(Order order) {
        this.currentOrder = order;
        this.status = ProcessingStatus.IN_PROGRESS;
        // process order...
    }
}

@Service
public class OrderService {
    private final ObjectProvider<OrderProcessor> processorProvider;

    public OrderService(ObjectProvider<OrderProcessor> provider) {
        this.processorProvider = provider;
    }

    public void handleOrder(Order order) {
        var processor = processorProvider.getObject(); // fresh instance
        processor.process(order);
        // each order gets its own processor instance
    }
}

// Problem: prototype injected into singleton
@Component
@Scope("prototype")
class OrderProcessor {
    private Order currentOrder; // stateful
}

@Service
class OrderService {
    private final OrderProcessor processor; // BAD: only one instance ever

    public OrderService(OrderProcessor processor) {
        this.processor = processor; // injected once at startup
    }

    public void processOrder(Order order) {
        processor.process(order); // always uses same processor instance!
    }
}

// Solution 1: Use ObjectProvider
@Service
class OrderService {
    private final ObjectProvider<OrderProcessor> processorProvider;

    public OrderService(ObjectProvider<OrderProcessor> provider) {
        this.processorProvider = provider;
    }

    public void processOrder(Order order) {
        var processor = processorProvider.getObject(); // fresh instance
        processor.process(order);
    }
}

@Service // singleton by default
public class OrderService {
    private final OrderRepository orderRepository; // immutable reference
    private final PaymentGateway paymentGateway;   // injected dependency

    public OrderService(OrderRepository repo, PaymentGateway gateway) {
        this.orderRepository = repo;
        this.paymentGateway = gateway;
    }

    // Stateless: no instance fields modified, all state in parameters
    public Order createOrder(Long userId, List<OrderItem> items) {
        var total = items.stream()
            .mapToDouble(OrderItem::getPrice)
            .sum();
        var order = new Order(userId, items, total, LocalDateTime.now());
        orderRepository.save(order);
        return order; // thread-safe: each call is independent
    }

    // Another thread calling this concurrently is safe
    public void cancelOrder(Long orderId) {
        var order = orderRepository.findById(orderId)
            .orElseThrow(() -> new OrderNotFoundException(orderId));
        order.cancel();
        orderRepository.save(order);
    }
}
